question.answer:
def drain(readings):
    index = 0
    while readings[index] != -1:
        print("reading", readings[index])
        index = index + 1
    print("sentinel reached")

def scan(codes):
    for code in codes:
        if code == 0:
            continue
        if code < 0:
            print("abort")
            break
        print("code", code)

def find_fault(codes):
    for code in codes:
        if code > 100:
            print("fault", code)
            break
    else:
        print("all clear")
